class Solution { public: ListNode* reverseEvenLengthGroups(ListNode* head){ListNode dummy(0,head),*previous=&dummy,*start=head;for(int group=1;start;group++){ListNode* cursor=start;int actual=0;while(cursor&&actual<group){cursor=cursor->next;++actual;}if(actual%2==0){ListNode *node=start,*reversed=cursor;while(node!=cursor){ListNode* next=node->next;node->next=reversed;reversed=node;node=next;}previous->next=reversed;previous=start;}else while(actual--)previous=previous->next;start=cursor;}return dummy.next;} };
